// Parse the JSON results and extract key data
const fileContent = $input.first().json.data;
const results = JSON.parse(fileContent);

const macro = results.macro || {};
const portfolio = results.portfolio || [];

// Verdict counts
const counts = { Buy: 0, Hold: 0, Pass: 0, Avoid: 0 };
for (const stock of portfolio) {
  if (counts.hasOwnProperty(stock.verdict)) {
    counts[stock.verdict]++;
  }
}

// Top 3 by score
const sorted = [...portfolio].sort((a, b) => b.score - a.score);
const top3 = sorted.slice(0, 3).map(s => ({
  ticker: s.ticker,
  company: s.company,
  score: s.score,
  verdict: s.verdict,
  price: s.price,
  one_year_target: s.one_year_target,
  upside_pct: s.upside_pct
}));

// Stocks with earnings within 7 days
const earningsAlerts = portfolio.filter(s => {
  return s.earnings_countdown_days !== null &&
         s.earnings_countdown_days >= 0 &&
         s.earnings_countdown_days <= 7;
}).map(s => ({
  ticker: s.ticker,
  company: s.company,
  next_earnings: s.next_earnings,
  countdown_days: s.earnings_countdown_days,
  verdict: s.verdict
}));

// Full portfolio summary sorted by score
const summaryTable = sorted.map(s => ({
  ticker: s.ticker,
  company: s.company,
  verdict: s.verdict,
  score: s.score,
  price: s.price,
  one_year_target: s.one_year_target,
  upside_pct: s.upside_pct,
  earnings_countdown_days: s.earnings_countdown_days,
  sector: s.sector
}));

return [{
  json: {
    generated_at: results.generated_at,
    macro: {
      overall_signal: macro.overall_signal,
      overall_score: macro.overall_score,
      recession_probability: macro.recession_probability
    },
    counts: counts,
    top3: top3,
    earningsAlerts: earningsAlerts,
    summaryTable: summaryTable,
    totalStocks: portfolio.length
  }
}];

const data = $input.first().json;
const d = data.generated_at ? data.generated_at.split('T')[0] : new Date().toISOString().split('T')[0];

// --- Header ---
let msg = '';
msg += '='.repeat(50) + '\n';
msg += `PORTFOLIO ANALYZER DAILY REPORT - ${d}\n`;
msg += '='.repeat(50) + '\n\n';

// --- Macro Environment ---
const macro = data.macro;
msg += 'MACRO ENVIRONMENT\n';
msg += '-'.repeat(30) + '\n';
msg += `Signal:                ${macro.overall_signal} (${macro.overall_score}/10)\n`;
msg += `Recession Probability: ${macro.recession_probability}\n\n`;

// --- Verdict Breakdown ---
const c = data.counts;
msg += 'VERDICT BREAKDOWN\n';
msg += '-'.repeat(30) + '\n';
msg += `Buy: ${c.Buy}  |  Hold: ${c.Hold}  |  Pass: ${c.Pass}  |  Avoid: ${c.Avoid}\n`;
msg += `Total stocks analyzed: ${data.totalStocks}\n\n`;

// --- Top 3 Picks ---
msg += 'TOP 3 PICKS\n';
msg += '-'.repeat(50) + '\n';
msg += 'Ticker  Score  Verdict  Price     Target    Upside\n';
msg += '-'.repeat(50) + '\n';
for (const s of data.top3) {
  const ticker = (s.ticker || '').padEnd(8);
  const score = String(s.score != null ? s.score.toFixed(1) : 'N/A').padEnd(7);
  const verdict = (s.verdict || '').padEnd(9);
  const price = s.price != null ? ('$' + s.price.toFixed(2)).padEnd(10) : 'N/A'.padEnd(10);
  const target = s.one_year_target != null ? ('$' + s.one_year_target.toFixed(2)).padEnd(10) : 'N/A'.padEnd(10);
  const upside = s.upside_pct != null ? (s.upside_pct > 0 ? '+' : '') + s.upside_pct.toFixed(1) + '%' : 'N/A';
  msg += `${ticker}${score}${verdict}${price}${target}${upside}\n`;
}
msg += '\n';

// --- Earnings Alerts ---
if (data.earningsAlerts && data.earningsAlerts.length > 0) {
  msg += 'EARNINGS ALERTS (within 7 days)\n';
  msg += '-'.repeat(40) + '\n';
  for (const a of data.earningsAlerts) {
    const urgency = a.countdown_days <= 2 ? ' *** IMMINENT ***' : '';
    msg += `${a.ticker} (${a.company}) - Earnings in ${a.countdown_days} day(s) [${a.next_earnings}]${urgency}\n`;
  }
  msg += '\n';
} else {
  msg += 'EARNINGS ALERTS: None within 7 days\n\n';
}

// --- Full Portfolio Summary ---
msg += 'FULL PORTFOLIO (sorted by score)\n';
msg += '-'.repeat(60) + '\n';
msg += 'Ticker  Score  Verdict  Price     Target    Upside   Earnings\n';
msg += '-'.repeat(60) + '\n';
for (const s of data.summaryTable) {
  const ticker = (s.ticker || '').padEnd(8);
  const score = String(s.score != null ? s.score.toFixed(1) : 'N/A').padEnd(7);
  const verdict = (s.verdict || '').padEnd(9);
  const price = s.price != null ? ('$' + s.price.toFixed(2)).padEnd(10) : 'N/A'.padEnd(10);
  const target = s.one_year_target != null ? ('$' + s.one_year_target.toFixed(2)).padEnd(10) : 'N/A'.padEnd(10);
  const upside = s.upside_pct != null ? ((s.upside_pct > 0 ? '+' : '') + s.upside_pct.toFixed(1) + '%').padEnd(9) : 'N/A'.padEnd(9);
  const earn = s.earnings_countdown_days != null ? s.earnings_countdown_days + 'd' : '-';
  msg += `${ticker}${score}${verdict}${price}${target}${upside}${earn}\n`;
}
msg += '\n' + '='.repeat(50) + '\n';
msg += 'Generated by Ultimate Stock Portfolio Analyzer\n';

return [{ json: { message: msg, ...data } }];

// Error handler: captures failure from the analyzer script
const errorItem = $input.first();
const errorMsg = errorItem.json.stderr || errorItem.json.error || 'Unknown error';
const exitCode = errorItem.json.exitCode || 'N/A';
const now = new Date().toISOString().split('T')[0];

const message = [
  '='.repeat(50),
  `PORTFOLIO ANALYZER ERROR - ${now}`,
  '='.repeat(50),
  '',
  'The daily portfolio analysis FAILED.',
  '',
  `Exit Code: ${exitCode}`,
  `Error Output:`,
  errorMsg,
  '',
  'Please check:',
  '  1. Python environment and dependencies (yfinance, rich)',
  '  2. Network connectivity to Yahoo Finance',
  '  3. Disk space for /tmp/portfolio_results.json',
  '  4. Script path: /home/user/qlib',
  '',
  '='.repeat(50)
].join('\n');

return [{ json: { message: message, isError: true } }];
